// Check if we need to create a restart point
if (*counter >= restart_interval) {
    restarts->push_back(buffer->size());
    *counter = 0;
    *last_key = key.ToString();  // Full key at restart point
} else {
    // Calculate shared prefix length with last_key
    size_t shared = 0;
    const size_t min_length = std::min(last_key->size(), key.size());
    while ((shared < min_length) && ((*last_key)[shared] == key[shared])) {
        shared++;
    }

    // Update last_key to current key
    last_key->resize(shared);
    last_key->append(key.data() + shared, key.size() - shared);
}

// Encode shared, non_shared, and value_length as varints
PutVarint32(buffer, shared);
PutVarint32(buffer, key.size() - shared);
PutVarint32(buffer, value.size());

// Append the non-shared part of the key and the value
buffer->append(key.data() + shared, key.size() - shared);
buffer->append(value.data(), value.size());

// Increment the counter
(*counter)++;

